2	<title>Shift-Left Gates</title>
3	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&family=Archivo:ital,wght@0,400;0,500;0,600;0,700;0,800;1,500&display=swap">
4	<style>
5	  :root {
6	    /* page tokens — theme-aware */
7	    --ground: #eef2f0;
8	    --surface: #ffffff;
9	    --ink: #0d1512;
10	    --ink-soft: #4a5c53;
11	    --ink-faint: #7c8c85;
12	    --trace: #0e8f79;
13	    --trace-soft: #e2f5f0;
14	    --gate: #9a6316;
15	    --gate-soft: #fbf0de;
16	    --line: #d6e0db;
17	    --shadow: rgba(20, 40, 34, 0.08);
18	
19	    /* monitor tokens — deliberately theme-fixed (diagrams always read as a dark signal display) */
20	    --mono-void: #0a0d11;
21	    --mono-void-raised: #10151b;
22	    --mono-line: #263230;
23	    --mono-ink: #dbe6e2;
24	    --mono-ink-faint: #6d7d77;
25	    --mono-trace: #46e6c4;
26	    --mono-gate: #ffb454;
27	
28	    --font-display: "Space Mono", ui-monospace, "SF Mono", Menlo, monospace;
29	    --font-body: "Archivo", system-ui, -apple-system, "Segoe UI", sans-serif;
30	  }
31	
32	  @media (prefers-color-scheme: dark) {
33	    :root:not([data-theme="light"]) {
34	      --ground: #0b0f13;
35	      --surface: #131920;
36	      --ink: #e7ece9;
37	      --ink-soft: #9fb0a9;
38	      --ink-faint: #667670;
39	      --trace: #46e6c4;
40	      --trace-soft: #10302b;
41	      --gate: #ffb454;
42	      --gate-soft: #2c2210;
43	      --line: #202a27;
44	      --shadow: rgba(0, 0, 0, 0.4);
45	    }
46	  }
47	  :root[data-theme="dark"] {
48	    --ground: #0b0f13;
49	    --surface: #131920;
50	    --ink: #e7ece9;
51	    --ink-soft: #9fb0a9;
52	    --ink-faint: #667670;
53	    --trace: #46e6c4;
54	    --trace-soft: #10302b;
55	    --gate: #ffb454;
56	    --gate-soft: #2c2210;
57	    --line: #202a27;
58	    --shadow: rgba(0, 0, 0, 0.4);
59	  }
60	
61	  * { box-sizing: border-box; }
62	  html { scroll-behavior: smooth; }
63	  @media (prefers-reduced-motion: reduce) {
64	    html { scroll-behavior: auto; }
65	    * { animation: none !important; transition: none !important; }
66	  }
67	  body {
68	    margin: 0;
69	    background: var(--ground);
70	    color: var(--ink);
71	    font-family: var(--font-body);
72	    font-size: 16.5px;
73	    line-height: 1.6;
74	    -webkit-font-smoothing: antialiased;
75	  }
76	  a { color: var(--trace); }
77	  code, .mono { font-family: var(--font-display); }
78	
79	  /* ============ HERO ============ */
80	  .hero {
81	    position: relative;
82	    background: var(--mono-void);
83	    color: var(--mono-ink);
84	    overflow: hidden;
85	    padding: 5.5rem 6vw 4.5rem;
86	  }
87	  .hero-trace {
88	    position: absolute;
89	    inset: 0;
90	    width: 100%;
91	    height: 100%;
92	    opacity: 0.9;
93	  }
94	  .hero-trace path.line {
95	    fill: none;
96	    stroke: var(--mono-trace);
97	    stroke-width: 1.6;
98	    stroke-dasharray: 6 10;
99	    opacity: 0.55;
100	    animation: drift 26s linear infinite;
101	  }
102	  @keyframes drift { to { stroke-dashoffset: -640; } }
103	  .hero-trace circle.node { fill: var(--mono-void); stroke: var(--mono-trace); stroke-width: 1.6; }
104	  .hero-trace circle.gatept { fill: var(--mono-gate); }
105	  .hero-inner { position: relative; max-width: 1180px; margin: 0 auto; }
106	  .eyebrow {
107	    font-family: var(--font-display);
108	    font-size: 0.74rem;
109	    letter-spacing: 0.14em;
110	    text-transform: uppercase;
111	    color: var(--mono-trace);
112	    display: flex;
113	    gap: 0.6rem;
114	    align-items: center;
115	    margin-bottom: 1.6rem;
116	  }
117	  .eyebrow .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--mono-gate); box-shadow: 0 0 8px var(--mono-gate); }
118	  h1 {
119	    font-family: var(--font-display);
120	    font-weight: 700;
121	    font-size: clamp(2.6rem, 6.4vw, 5rem);
122	    line-height: 1.03;
123	    letter-spacing: -0.015em;
124	    margin: 0 0 1.6rem;
125	    text-wrap: balance;
126	    max-width: 16ch;
127	  }
128	  h1 em { font-style: normal; color: var(--mono-trace); }
129	  .thesis {
130	    font-family: var(--font-body);
131	    font-weight: 500;
132	    font-size: clamp(1.05rem, 1.6vw, 1.3rem);
133	    color: #b9c8c2;
134	    max-width: 46ch;
135	    margin: 0;
136	    text-wrap: balance;
137	  }
138	
139	  /* ============ RAIL SECTIONS ============ */
140	  main { max-width: 1180px; margin: 0 auto; padding: 0 6vw; }
141	  .rail-section {
142	    display: grid;
143	    grid-template-columns: 130px 1fr;
144	    gap: 2.2rem;
145	    padding: 4rem 0;
146	    border-bottom: 1px solid var(--line);
147	  }
148	  .rail-section:last-of-type { border-bottom: none; }
149	  .rail { padding-top: 0.25rem; }
150	  .rail-num {
151	    display: block;
152	    font-family: var(--font-display);
153	    font-weight: 700;
154	    font-size: 2.1rem;
155	    color: var(--line);
156	    line-height: 1;
157	  }
158	  .rail-label {
159	    display: block;
160	    margin-top: 0.5rem;
161	    font-family: var(--font-display);
162	    font-size: 0.7rem;
163	    letter-spacing: 0.1em;
164	    text-transform: uppercase;
165	    color: var(--trace);
166	  }
167	  @media (max-width: 720px) {
168	    .rail-section { grid-template-columns: 1fr; gap: 0.8rem; }
169	    .rail { display: flex; align-items: baseline; gap: 0.6rem; }
170	    .rail-num { font-size: 1.3rem; }
171	  }
172	
173	  h2 {
174	    font-family: var(--font-display);
175	    font-weight: 700;
176	    font-size: clamp(1.35rem, 2.2vw, 1.8rem);
177	    letter-spacing: -0.01em;
178	    margin: 0 0 0.9rem;
179	    text-wrap: balance;
180	  }
181	  p.lede { color: var(--ink-soft); max-width: 62ch; font-size: 1rem; margin: 0 0 1.6rem; }
182	  p.diagram-caption {
183	    font-family: var(--font-display);
184	    font-size: 0.74rem;
185	    color: var(--ink-faint);
186	    text-transform: uppercase;
187	    letter-spacing: 0.06em;
188	    margin: 0.8rem 0 0;
189	  }
190	
191	  /* ============ MONITOR (diagram panel — always dark) ============ */
192	  .monitor {
193	    background: var(--mono-void);
194	    border: 1px solid var(--mono-line);
195	    border-radius: 10px;
196	    padding: 1.6rem 1.4rem 1.8rem;
197	    box-shadow: 0 18px 40px -22px var(--shadow);
198	  }
199	  .monitor svg { display: block; width: 100%; height: auto; }
200	  .monitor svg text { font-family: var(--font-display); }
201	  .m-caption { fill: var(--mono-ink-faint); font-size: 10px; letter-spacing: 0.06em; text-transform: uppercase; }
202	  .m-box { fill: var(--mono-void-raised); stroke: var(--mono-line); stroke-width: 1.3; }
203	  .m-box.ghost { stroke-dasharray: 4 3; opacity: 0.75; }
204	  .m-label { fill: var(--mono-ink); font-size: 12.5px; font-weight: 700; }
205	  .m-sub { fill: var(--mono-ink-faint); font-size: 9.5px; }
206	  .m-flow { stroke: var(--mono-line); stroke-width: 1.5; fill: none; marker-end: url(#mArrow); }
207	  .m-flow.ghost { stroke-dasharray: 3 4; }
208	  .m-gate-dot { fill: var(--mono-gate); filter: drop-shadow(0 0 4px var(--mono-gate)); }
209	  .m-gate-ring { fill: none; stroke: var(--mono-gate); stroke-width: 1.3; opacity: 0.7; }
210	  .m-gate-label { fill: var(--mono-gate); font-size: 10px; font-weight: 700; }
211	  .m-loop { stroke: var(--mono-gate); stroke-width: 1.3; stroke-dasharray: 3 3; fill: none; marker-end: url(#mArrowGate); opacity: 0.85; }
212	  .m-loop-dot { fill: var(--mono-gate); }
213	  .m-loop-label { fill: #d9ac6b; font-size: 8.6px; }
214	
