218	  caption { text-align: left; font-family: var(--font-display); font-size: 0.7rem; color: var(--ink-faint); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 0.7rem; }
219	  th {
220	    text-align: left; font-family: var(--font-display); font-size: 0.68rem; text-transform: uppercase;
